class Solution {
public:
    bool confusingNumber(int n) {
        int rotation[10] = {0, 1, -1, -1, -1, -1, 9, -1, 8, 6};
        int original = n;
        long long reversed = 0;
        do {
            int digit = n % 10;
            if (rotation[digit] == -1) {
                return false;
            }
            reversed = reversed * 10 + rotation[digit];
            n /= 10;
        } while (n > 0);
        return reversed != original;
    }
};
